    "type": "definition",
    "recto": "En quoi consiste la méthode Delphi ?",
    "verso": "Une consultation itérative de panels d'experts, qui affinent leurs prévisions jusqu'à l'obtention d'un consensus.",
    "ancre": "s-6-anticipation-et-prospective",
